-- TORVO V2 PRODUCT ADS + POPULAR PRODUCTS
create table if not exists product_promotions(id uuid primary key default gen_random_uuid(),product_id uuid not null references products(id) on delete cascade,title text not null,caption text,image_url text,target text not null default 'both' check(target in('website','dealer_app','both')),active boolean not null default true,starts_at timestamptz not null default now(),ends_at timestamptz,sort_order int not null default 100,created_by uuid references app_users(id),updated_at timestamptz not null default now());
alter table products add column if not exists featured boolean not null default false;alter table products add column if not exists featured_rank int;
alter table product_promotions enable row level security;revoke all on product_promotions from anon,authenticated;
create or replace function public_active_product_promotions(p_target text default 'website') returns table(id uuid,product_id uuid,title text,caption text,image_url text,sort_order int) language plpgsql security definer set search_path=public as $$declare t text:=lower(btrim(coalesce(p_target,'website')));begin if t not in('website','dealer_app') then raise exception 'INVALID PROMOTION TARGET';end if;return query select a.id,a.product_id,a.title,a.caption,a.image_url,a.sort_order from product_promotions a join products p on p.id=a.product_id where a.active=true and p.active=true and a.starts_at<=now() and(a.ends_at is null or a.ends_at>=now())and(a.target='both' or a.target=t)order by a.sort_order,a.updated_at desc limit 24;end$$;
create or replace function public_popular_products(p_limit int default 12) returns setof products language sql security definer set search_path=public as $$select p.* from products p where p.active=true order by p.featured desc,p.featured_rank nulls last,p.updated_at desc limit least(greatest(coalesce(p_limit,12),1),30)$$;
create or replace function admin_save_product_promotion(p_id uuid,p_product_id uuid,p_title text,p_caption text default '',p_image_url text default null,p_target text default 'both',p_active boolean default true,p_starts_at timestamptz default now(),p_ends_at timestamptz default null,p_sort_order int default 100,p_reason text default null) returns uuid language plpgsql security definer set search_path=public as $$declare u app_users%rowtype;x uuid;t text:=lower(btrim(coalesce(p_target,'')));ttl text:=upper(btrim(coalesce(p_title,'')));cap text:=btrim(coalesce(p_caption,''));img text:=nullif(btrim(coalesce(p_image_url,'')),'');rsn text:=upper(btrim(coalesce(p_reason,'')));begin select * into u from app_users where auth_user_id=auth.uid() and active=true;if u.id is null or u.role not in('owner','admin')then raise exception 'OWNER OR ADMIN REQUIRED';end if;if p_product_id is null then raise exception 'PRODUCT REQUIRED';end if;if length(ttl)<2 or length(ttl)>120 then raise exception 'PROMOTION TITLE MUST BE 2 TO 120 CHARACTERS';end if;if length(cap)>500 then raise exception 'PROMOTION CAPTION MUST BE 500 CHARACTERS OR LESS';end if;if img is not null and length(img)>1000 then raise exception 'PROMOTION IMAGE URL MUST BE 1000 CHARACTERS OR LESS';end if;if length(rsn)<3 or length(rsn)>500 then raise exception 'CHANGE REASON MUST BE 3 TO 500 CHARACTERS';end if;if t not in('website','dealer_app','both')then raise exception 'INVALID PROMOTION TARGET';end if;if p_sort_order is null or p_sort_order<0 or p_sort_order>100000 then raise exception 'INVALID PROMOTION SORT ORDER';end if;if p_starts_at is null then raise exception 'PROMOTION START TIME REQUIRED';end if;if p_ends_at is not null and p_ends_at<=p_starts_at then raise exception 'END TIME MUST BE AFTER START TIME';end if;if not exists(select 1 from products where id=p_product_id and active=true)then raise exception 'ACTIVE PRODUCT REQUIRED';end if;if p_id is null then insert into product_promotions(product_id,title,caption,image_url,target,active,starts_at,ends_at,sort_order,created_by)values(p_product_id,ttl,cap,img,t,coalesce(p_active,true),p_starts_at,p_ends_at,p_sort_order,u.id)returning id into x;else update product_promotions set product_id=p_product_id,title=ttl,caption=cap,image_url=img,target=t,active=coalesce(p_active,true),starts_at=p_starts_at,ends_at=p_ends_at,sort_order=p_sort_order,updated_at=now() where id=p_id returning id into x;if x is null then raise exception 'PROMOTION NOT FOUND';end if;end if;insert into audit_log(actor_id,action,entity_type,entity_id,details)values(u.id,'PRODUCT_PROMOTION_SAVED','PRODUCT_PROMOTION',x::text,jsonb_build_object('reason',rsn,'product_id',p_product_id,'target',t));return x;end$$;
create or replace function admin_set_product_featured(p_product_id uuid,p_featured boolean,p_rank int default null,p_reason text default null) returns boolean language plpgsql security definer set search_path=public as $$declare u app_users%rowtype;begin select * into u from app_users where auth_user_id=auth.uid() and active=true;if u.id is null or u.role not in('owner','admin')then raise exception 'OWNER OR ADMIN REQUIRED';end if;if nullif(btrim(coalesce(p_reason,'')),'')is null then raise exception 'CHANGE REASON REQUIRED';end if;update products set featured=coalesce(p_featured,false),featured_rank=case when p_featured then p_rank else null end,updated_at=now() where id=p_product_id;if not found then raise exception 'PRODUCT NOT FOUND';end if;insert into audit_log(actor_id,action,entity_type,entity_id,details)values(u.id,'PRODUCT_FEATURED_CHANGED','PRODUCT',p_product_id::text,jsonb_build_object('featured',p_featured,'rank',p_rank,'reason',upper(btrim(p_reason))));return true;end$$;
revoke all on function public_active_product_promotions(text),public_popular_products(int),admin_save_product_promotion(uuid,uuid,text,text,text,text,boolean,timestamptz,timestamptz,int,text),admin_set_product_featured(uuid,boolean,int,text) from public;grant execute on function public_active_product_promotions(text),public_popular_products(int) to anon,authenticated;grant execute on function admin_save_product_promotion(uuid,uuid,text,text,text,text,boolean,timestamptz,timestamptz,int,text),admin_set_product_featured(uuid,boolean,int,text) to authenticated;
